import { Card } from "../../card/card";
import { convertCardSizeToState } from "./convertCardSizeToState";
import { SummaryTile } from "../../summaryTile/summaryTile";
import { Table } from "../../table/table";
import { Banner } from "../../banner/banner";
import { convertBannerSizeToState } from "./convertBannerSizeToState";
import { Accordion } from "../../accordion/accordion";
import { CardContainer } from "../../cardContainer/cardContainer";
import { BannerUpsell } from "../../banner/bannerUpsell";
import { FormStepper } from "../../formStepper/formStepper";
import { FormStepperButtons } from "../../formStepperButtons/formStepperButtons";
export const updateGridStateWithDefaultValues = (item, gridState) => {
    const { lg, md, sm } = gridState;
    if (lg || md || sm) {
        return;
    }
    if (item.type === Card) {
        const { lg: cardLg } = convertCardSizeToState(item);
        gridState.lg = cardLg;
    }
    if (item.type === CardContainer) {
        const { lg: cardLg } = convertCardSizeToState(item);
        gridState.lg = cardLg;
    }
    if (item.type === SummaryTile) {
        gridState.lg = 2;
    }
    if (item.type === Table) {
        gridState.lg = 12;
    }
    if (item.type === Banner || item.type === BannerUpsell) {
        const { lg: bannerLg } = convertBannerSizeToState(item);
        gridState.lg = bannerLg;
    }
    if (item.type === Accordion) {
        gridState.lg = 7;
    }
    if (item.type === FormStepper) {
        gridState.lg = 12;
    }
    if (item.type === FormStepperButtons) {
        gridState.lg = 12;
    }
};
